import zipfile
import re
import xml.etree.ElementTree as ET

NS = {"m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}


def col_letter(ref):
    return re.match(r"[A-Z]+", ref).group(0)


def col_index(letters):
    n = 0
    for ch in letters:
        n = n * 26 + (ord(ch) - 64)
    return n


def row_index(ref):
    return int(re.search(r"\d+", ref).group(0))


def main():
    path = "budget.xlsx"
    z = zipfile.ZipFile(path)
    names = z.namelist()
    shared = []
    if "xl/sharedStrings.xml" in names:
        root = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in root.findall("m:si", NS):
            text = "".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
            shared.append(text)
    sheets = {}
    for n in names:
        mm = re.match(r"xl/worksheets/sheet(\d+)\.xml", n)
        if mm:
            sheets[int(mm.group(1))] = n
    for idx in sorted(sheets):
        root = ET.fromstring(z.read(sheets[idx]))
        grid = {}
        for c in root.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}c"):
            ref = c.get("r")
            if not ref:
                continue
            t = c.get("t")
            v = c.find("m:v", NS)
            is_ = c.find("m:is", NS)
            if v is not None and v.text is not None:
                val = v.text
                if t == "s":
                    val = shared[int(val)]
                elif t == "b":
                    val = val == "1"
            elif is_ is not None:
                val = "".join(x.text or "" for x in is_.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
            else:
                val = ""
            grid[(row_index(ref), col_index(col_letter(ref)))] = val
        print("SHEET", idx, "rows", max((r for r, cc in grid), default=0), "cols", max((cc for r, cc in grid), default=0))
        for r in sorted({r for r, cc in grid}):
            vals = [grid.get((r, cc), "") for cc in range(1, max((cc for rr, cc in grid), default=0) + 1)]
            print(r, vals)


if __name__ == "__main__":
    main()

